# -----------------------------
# HELPERS
# -----------------------------
def split_key(key):
    parts = key.split("|")
    return parts[0], parts[1], parts[2]

def athlete_records_for_sport(sport_code):
    """
    Return (display_name, exact_bank_key) pairs.
    The exact key is carried forward from the bank, so selecting a player can
    never fail because of capitalization, emoji, league labels, or name formatting.
    """
    records = []
    for key, challenges in QUESTION_BANK.items():
        s, league, athlete_from_key = split_key(key)
        if s != sport_code:
            continue

        # Recover the properly-capitalized athlete name from the question text
        # when possible; otherwise use a safe display version of the key name.
        display_name = athlete_from_key
        if athlete_from_key.islower():
            display_name = athlete_from_key.title()

        # Correct common surname casing that title() damages.
        casing_fixes = {
            "Mcdavid": "McDavid",
            "Mccaffrey": "McCaffrey",
            "Mclaurin": "McLaurin",
            "Mckinnon": "McKinnon",
            "Mcilroy": "McIlroy",
            "O'neill": "O'Neill",
            "D'angelo": "D'Angelo",
        }
        for bad, good in casing_fixes.items():
            display_name = display_name.replace(bad, good)

        records.append((display_name, key))

    records.sort(key=lambda x: x[0].lower())
    return records

def clean_label(text):
    text = str(text or "").strip()
    return text if text else "Label"

def numeric_value(value):
    """Accept commas, %, currency symbols, + signs, etc. Never reject a valid-looking number."""
    if value is None:
        return None
    text = str(value).strip()
    if not text:
        return None
    for ch in [",", "%", "$", "+"]:
        text = text.replace(ch, "")
    try:
        return float(text)
    except Exception:
        return None

def reset_investigation():
    for key in [
        "active_question","evidence","observation","original_claim","coach_reply",
        "coach_answer","revised_claim","final_feedback","score_result"
    ]:
        st.session_state.pop(key, None)

def universal_columns(challenge):
    """
    Universal rule:
    first evidence field is descriptive/category;
    all remaining fields are numeric.
    This is the ONLY graph schema in the app.
    """
    fields = challenge.get("schema", {}).get("fields", [])
    if len(fields) < 2:
        return ["Label", "Value"]
    return [clean_label(f.get("label")) for f in fields]

def make_graph(rows, columns):
    """
    No sport-specific logic.
    Column 0 = x-axis label.
    Columns 1+ = numeric series.
    """
    chart_rows = []
    for row in rows:
        label = str(row.get(columns[0], "")).strip()
        if not label:
            return None, f"Enter a label in every **{columns[0]}** box."
        item = {columns[0]: label}
        for col in columns[1:]:
            val = numeric_value(row.get(col))
            if val is None:
                return None, f"Enter a number in every **{col}** box."
            item[col] = val
        chart_rows.append(item)

    spec = {
        "mark": {"type": "bar", "tooltip": True},
        "encoding": {
            "x": {"field": columns[0], "type": "nominal", "title": columns[0]},
            "y": {"field": "value", "type": "quantitative", "title": "Value"},
            "color": {"field": "stat", "type": "nominal", "title": "Statistic"},
            "xOffset": {"field": "stat"}
        },
        "transform": [{
            "fold": columns[1:],
            "as": ["stat", "value"]
        }],
        "data": {"values": chart_rows}
    }
    return spec, None

def ask_coach(question, rows, observation, claim, student_answer=""):
    if not client:
        return "AI Coach is unavailable right now."
    prompt = f"""
You are a supportive Sports Data Coach for a 7th-grade statistics class.

INVESTIGATION:
{question}

STUDENT-ENTERED EVIDENCE (unverified):
{json.dumps(rows)}

WHAT THE STUDENT NOTICED:
{observation}

STUDENT'S CLAIM:
{claim}

STUDENT'S LATEST ANSWER TO THE COACH:
{student_answer or "(none yet)"}

Rules:
- Never supply missing sports statistics.
- Treat the student's entered numbers as unverified.
- Do not write the claim for the student.
- Focus on whether the claim matches the evidence and whether the reasoning is clear.
- Use simple grade-7 language.
- Ask exactly ONE short question if the student still needs to think.
- If the student is ready to revise, end with exactly: READY TO REVISE
- Keep the whole response under 90 words.
"""
    try:
        r = client.responses.create(
            model="gpt-5.6-luna",
            input=prompt,
            max_output_tokens=180
        )
        return r.output_text.strip()
    except Exception as e:
        if "429" in str(e) or "rate" in str(e).lower():
            return "AI Coach is temporarily unavailable because the class API limit has been reached. Your evidence and claim are saved on this page."
        return "AI Coach is temporarily unavailable. Your work is still saved on this page."

def score_argument(question, rows, observation, original, revised):
    if not client:
        return None
    prompt = f"""
Grade this 7th-grade sports-data ARGUMENT, not whether the sports conclusion is factually correct.
Treat all student-entered statistics as unverified.

Question: {question}
Evidence: {json.dumps(rows)}
Observation: {observation}
Original claim: {original}
Revised claim: {revised}

Score:
Clear Claim /25
Use of Evidence /25
Reasoning /25
Strength & Fairness /25

Do not grade spelling unless meaning is unclear.
Return ONLY JSON:
{{"claim":0,"evidence":0,"reasoning":0,"fairness":0,"strength":"one short strength","next_step":"one short next step"}}
"""
    try:
        r = client.responses.create(model="gpt-5.6-luna", input=prompt, max_output_tokens=220)
        raw = r.output_text.replace("```json","").replace("```","").strip()
        data = json.loads(raw)
        for k in ["claim","evidence","reasoning","fairness"]:
            data[k] = max(0, min(25, int(data[k])))
        data["total"] = data["claim"]+data["evidence"]+data["reasoning"]+data["fairness"]
        return data
    except Exception:
        return None

