# HEADER
# -----------------------------
st.title("🏟️ Sports Data Investigator")
st.caption("Research the numbers yourself. Use the app to organize evidence, see the pattern, and defend a claim.")

# -----------------------------
# STEP 1 — PICK ATHLETE
# -----------------------------
st.markdown('<div class="step">Step 1 · Choose your athlete</div>', unsafe_allow_html=True)

sport_display = [v[0] for v in SPORT_INFO.values()]
selected_display = st.selectbox("Sport", sport_display)
sport_code = next(k for k,v in SPORT_INFO.items() if v[0] == selected_display)

athlete_records = athlete_records_for_sport(sport_code)

if not athlete_records:
    st.error(f"No athletes were found for {selected_display}.")
    st.stop()

athlete_names = [name for name, key in athlete_records]
athlete = st.selectbox("Athlete", athlete_names)
st.caption(f"Player pool loaded: {len(athlete_names)} athletes")

# Use the exact bank key attached to the selected player.
selected_index = athlete_names.index(athlete)
bank_key = athlete_records[selected_index][1]
challenges = QUESTION_BANK.get(bank_key, [])

if not challenges:
    st.error("This athlete does not have a prebuilt investigation set yet.")
    st.stop()

question_labels = [f"{c['type']} — {c['student_question']}" for c in challenges]
choice_index = st.selectbox(
    "Choose an investigation",
    range(len(challenges)),
    format_func=lambda i: question_labels[i]
)
selected_challenge = challenges[choice_index]

st.markdown(
    f'<div class="mission"><b>{selected_challenge["student_question"]}</b><br><br>'
    f'<span style="color:#dbeafe">{selected_challenge.get("why_this_athlete","")}</span></div>',
    unsafe_allow_html=True
)

if st.button("🚀 Start This Investigation", use_container_width=True):
    reset_investigation()
    st.session_state.active_question = selected_challenge
    rows_needed = int(selected_challenge.get("evidence_rows", 3))
    columns = universal_columns(selected_challenge)
    st.session_state.evidence = [
        {col: "" for col in columns} for _ in range(rows_needed)
    ]
    st.rerun()

if "active_question" not in st.session_state:
    st.stop()

challenge = st.session_state.active_question
columns = universal_columns(challenge)
rows_needed = int(challenge.get("evidence_rows", 3))

# Repair evidence state safely if question schema changes.
if "evidence" not in st.session_state or len(st.session_state.evidence) != rows_needed:
    st.session_state.evidence = [{col:"" for col in columns} for _ in range(rows_needed)]

# -----------------------------
# STEP 2 — EVIDENCE
# -----------------------------
st.markdown("---")
st.markdown('<div class="step">Step 2 · Enter your evidence</div>', unsafe_allow_html=True)
st.subheader(challenge["student_question"])
st.caption("Use a trusted sports statistics site. The app does not look up the numbers for you.")

for i in range(rows_needed):
    st.markdown(f"**Evidence row {i+1} of {rows_needed}**")
    cols = st.columns(len(columns))
    for j, col_name in enumerate(columns):
        with cols[j]:
            key = f"ev_{challenge['id']}_{i}_{j}"
            current = st.session_state.evidence[i].get(col_name, "")
            if j == 0:
                value = st.text_input(col_name, value=str(current), key=key)
            else:
                # Text input intentionally accepts 1,234 / 52.4 / 88% etc.;
                # numeric parsing happens only when graphing.
                value = st.text_input(col_name, value=str(current), key=key, placeholder="Number")
            st.session_state.evidence[i][col_name] = value

# -----------------------------
# STEP 3 — GRAPH
# -----------------------------
st.markdown("---")
st.markdown('<div class="step">Step 3 · See the pattern</div>', unsafe_allow_html=True)

graph_spec, graph_error = make_graph(st.session_state.evidence, columns)

if graph_error:
    st.info(graph_error)
else:
    st.vega_lite_chart(graph_spec, use_container_width=True)
    st.success("Graph ready — it uses exactly the numbers you entered.")

observation = st.text_area(
    "What do you notice in the graph?",
    value=st.session_state.get("observation",""),
    placeholder="I notice that...",
    height=90
)
st.session_state.observation = observation

# -----------------------------
# STEP 4 — CLAIM
# -----------------------------
st.markdown("---")
st.markdown('<div class="step">Step 4 · Make your claim</div>', unsafe_allow_html=True)

claim = st.text_area(
    "What does your evidence make you think?",
    value=st.session_state.get("original_claim",""),
    placeholder="Based on the evidence, I think...",
    height=110
)
st.session_state.original_claim = claim

ready_for_coach = (graph_error is None and observation.strip() and claim.strip())

if st.button("🤖 Ask the Sports Data Coach", disabled=not ready_for_coach, use_container_width=True):
    st.session_state.coach_reply = ask_coach(
        challenge["student_question"],
        st.session_state.evidence,
        observation,
        claim
    )
    st.rerun()

# -----------------------------
# STEP 5 — COACH
# -----------------------------
if st.session_state.get("coach_reply"):
    st.markdown("---")
    st.markdown('<div class="step">Step 5 · Coach</div>', unsafe_allow_html=True)
    st.markdown(f'<div class="card">🤖 <b>Coach:</b><br>{st.session_state.coach_reply}</div>', unsafe_allow_html=True)

    answer = st.text_area(
        "Answer your coach",
        value=st.session_state.get("coach_answer",""),
        height=90
    )
    st.session_state.coach_answer = answer

    c1,c2 = st.columns(2)
    with c1:
        if st.button("💬 Send Answer", disabled=not answer.strip(), use_container_width=True):
            st.session_state.coach_reply = ask_coach(
                challenge["student_question"],
                st.session_state.evidence,
                observation,
                claim,
                answer
            )
            st.rerun()
    with c2:
        if st.button("✏️ I'm Ready to Revise", use_container_width=True):
            st.session_state.ready_to_revise = True
            st.rerun()

# -----------------------------
# STEP 6 — REVISE + SCORE
# -----------------------------
if st.session_state.get("ready_to_revise") or "READY TO REVISE" in st.session_state.get("coach_reply",""):
    st.markdown("---")
    st.markdown('<div class="step">Step 6 · Revise</div>', unsafe_allow_html=True)
    st.markdown(f"**Your first claim:** {claim}")

    revised = st.text_area(
        "Write your stronger final claim",
        value=st.session_state.get("revised_claim",""),
        placeholder="After looking again at my evidence...",
        height=120
    )
    st.session_state.revised_claim = revised

    if st.button("🏆 Score My Argument", disabled=not revised.strip(), use_container_width=True):
        st.session_state.score_result = score_argument(
            challenge["student_question"],
            st.session_state.evidence,
            observation,
            claim,
            revised
        )
        st.rerun()

if st.session_state.get("score_result"):
    s = st.session_state.score_result
    st.markdown("---")
    st.markdown('<div class="step">Final · Argument score</div>', unsafe_allow_html=True)
    st.markdown(f'<div class="score">{s["total"]}/100</div>', unsafe_allow_html=True)
    a,b,c,d = st.columns(4)
    a.metric("Clear Claim", f'{s["claim"]}/25')
    b.metric("Evidence", f'{s["evidence"]}/25')
    c.metric("Reasoning", f'{s["reasoning"]}/25')
    d.metric("Strength & Fairness", f'{s["fairness"]}/25')
    st.success(f'**Strength:** {s.get("strength","")}')
    st.info(f'**Next step:** {s.get("next_step","")}')

st.markdown("---")
st.caption("Sports by the Numbers · Student-entered statistics are not independently verified by the app.")
